```cpp
#include <iostream>
using namespace std;

int main() {
    double num1, num2;
    char op;

cout << "請輸入運算式（例如 5 + 3）: ";
    cin >> num1 >> op >> num2;

switch (op) {
        case '+':
            cout << "結果: " << num1 + num2 << endl;
            break;
        case '-':
            cout << "結果: " << num1 - num2 << endl;
            break;
        case '*':
            cout << "結果: " << num1 * num2 << endl;
            break;
        case '/':
            if (num2 != 0) {
                cout << "結果: " << num1 / num2 << endl;
            } else {
                cout << "錯誤：不能除以 0" << endl;
            }
            break;
        default:
            cout << "錯誤：不支援的運算符號" << endl;
    }

return 0;
}
```

這個程式支援 `+`、`-`、`*`、`/` 四則運算，可直接編譯執行。  
輸入格式例如：`12.5 * 4`
